require 'aws-sdk-s3'

# Description: Sublayer::Action responsible for uploading files to Amazon S3 buckets.
# This action enables easy integration with AWS S3 storage for files generated by AI workflows.
#
# Requires: 'aws-sdk-s3' gem
# $ gem install aws-sdk-s3
# Or add `gem 'aws-sdk-s3'` to your Gemfile
#
# It is initialized with bucket_name, file_path (the S3 key/path), and file_content.
# Returns the URL of the uploaded file on successful upload.
#
# Example usage: When you want to store AI-generated files (documents, images, etc.)
# in S3 for later access or distribution.

class S3UploadFileAction < Sublayer::Actions::Base
  def initialize(bucket_name:, file_path:, file_content:, content_type: nil, public_read: false)
    @bucket_name = bucket_name
    @file_path = file_path
    @file_content = file_content
    @content_type = content_type
    @public_read = public_read
    @client = Aws::S3::Client.new(
      access_key_id: ENV['AWS_ACCESS_KEY_ID'],
      secret_access_key: ENV['AWS_SECRET_ACCESS_KEY'],
      region: ENV['AWS_REGION']
    )
  end

  def call
    begin
      upload_options = {
        bucket: @bucket_name,
        key: @file_path,
        body: @file_content
      }

      # Add optional parameters if provided
      upload_options[:content_type] = @content_type if @content_type
      upload_options[:acl] = 'public-read' if @public_read

      # Perform the upload
      @client.put_object(upload_options)

      # Generate the URL for the uploaded file
      url = generate_file_url

      Sublayer.configuration.logger.log(:info, "Successfully uploaded file to S3: #{url}")
      url
    rescue Aws::S3::Errors::ServiceError => e
      error_message = "S3 service error: #{e.message}"
      Sublayer.configuration.logger.log(:error, error_message)
      raise StandardError, error_message
    rescue StandardError => e
      error_message = "Error uploading file to S3: #{e.message}"
      Sublayer.configuration.logger.log(:error, error_message)
      raise e
    end
  end

  private

  def generate_file_url
    if @public_read
      "https://#{@bucket_name}.s3.#{ENV['AWS_REGION']}.amazonaws.com/#{@file_path}"
    else
      # Generate a presigned URL that expires in 1 hour for private files
      signer = Aws::S3::Presigner.new(client: @client)
      signer.presigned_url(:get_object, 
        bucket: @bucket_name,
        key: @file_path,
        expires_in: 3600
      )
    end
  end
end